// Option B: hledger as a long-lived reactor module. The parsed journal stays in
// memory between calls (cached inside the module by input files + input options);
// mount() replaces the files and invalidates that cache.
import { ConsoleStdout, File, OpenFile, PreopenDirectory, WASI } from '@bjorn3/browser_wasi_shim';
import type { RawResult } from '../contracts/engine';
import { buildTree, VAULT_ROOT, type EngineBackend } from './backend';

/** The GHC JSFFI glue module's default export (generated by post-link.mjs). */
export type JsffiFactory = (exportsRef: Record<string, unknown>) => WebAssembly.ModuleImports;

interface ReactorExports {
  memory: WebAssembly.Memory;
  hs_init(argc: number, argv: number): void;
  hledgerRun(argsJson: string): string | Promise<string>;
  hledgerInvalidate(): void;
  hledgerVersion(): string;
}

export class ReactorBackend implements EngineBackend {
  readonly mode = 'reactor' as const;
  private constructor(
    private readonly ex: ReactorExports,
    private readonly root: PreopenDirectory,
  ) {}

  static async create(module: WebAssembly.Module, jsffi: JsffiFactory): Promise<ReactorBackend> {
    const root = new PreopenDirectory(VAULT_ROOT, new Map());
    const wasi = new WASI([], ['HOME=/nonexistent', 'LC_ALL=C.UTF-8', 'TZ=UTC'], [
      new OpenFile(new File(new Uint8Array())),
      ConsoleStdout.lineBuffered(() => {}),
      ConsoleStdout.lineBuffered(() => {}),
      root,
    ], { debug: false });
    const exportsRef: Record<string, unknown> = {};
    const instance = await WebAssembly.instantiate(module, {
      wasi_snapshot_preview1: wasi.wasiImport,
      ghc_wasm_jsffi: jsffi(exportsRef),
    });
    Object.assign(exportsRef, instance.exports);
    wasi.initialize(instance as unknown as { exports: { memory: WebAssembly.Memory; _initialize?: () => unknown } });
    const ex = instance.exports as unknown as ReactorExports;
    ex.hs_init(0, 0);
    return new ReactorBackend(ex, root);
  }

  mount(files: Record<string, string | Uint8Array>) {
    this.root.dir.contents = buildTree(files);
    this.ex.hledgerInvalidate();
  }

  async run(args: string[]): Promise<RawResult> {
    try {
      return JSON.parse(await this.ex.hledgerRun(JSON.stringify(args))) as RawResult;
    } catch (e) {
      return { code: 70, stdout: '', stderr: `engine trap: ${(e as Error).message ?? e}` };
    }
  }

  version(): string {
    return this.ex.hledgerVersion();
  }
}
